<?php
// Protected customer dashboard: combines account summaries, quick actions and recent demo banking activity.
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
require_login();
require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/includes/helpers.php';
$pdo = db();
$userId = $_SESSION['user_id'];
$userStatement = $pdo->prepare('SELECT first_name, last_name FROM users WHERE id = ?'); $userStatement->execute([$userId]); $user = $userStatement->fetch();
$accountsStatement = $pdo->prepare('SELECT * FROM accounts WHERE user_id = ? ORDER BY FIELD(account_type, "Chequing", "Savings", "Investment")'); $accountsStatement->execute([$userId]); $accounts = $accountsStatement->fetchAll();
$total = array_sum(array_map(fn($account) => (float) $account['balance'], $accounts));
$transactionsStatement = $pdo->prepare('SELECT t.*, a.account_type FROM transactions t JOIN accounts a ON a.id = t.account_id WHERE a.user_id = ? ORDER BY t.transaction_date DESC LIMIT 5'); $transactionsStatement->execute([$userId]); $transactions = $transactionsStatement->fetchAll();
$pageTitle = 'Dashboard'; $portal = true; require __DIR__ . '/includes/header.php';
?>
<section class="portal-shell"><div class="portal-welcome"><div><p class="eyebrow">Customer dashboard</p><h1>Good to see you, <?= e($user['first_name'] ?? 'Member') ?>.</h1><p>Here is the fictional DDB picture at a glance.</p></div><p class="demo-badge">Demo data only</p></div><div class="balance-hero"><div><span>Total balance</span><strong><?= money($total) ?></strong><p>Across <?= count($accounts) ?> active accounts</p></div><a class="button button-light" href="transfer.php">Transfer money →</a></div><div class="quick-actions" aria-label="Quick actions"><a href="transfer.php"><span>↗</span>Transfer Money</a><a href="statements.php"><span>▤</span>Pay Bill</a><a href="statements.php"><span>↓</span>View Statements</a><a href="portfolio.php"><span>◒</span>Invest</a></div><section class="portal-section"><div class="section-heading portal-heading"><div><p class="eyebrow">Account summary</p><h2>Keep the essentials close.</h2></div><a class="text-action" href="accounts.php">View all accounts →</a></div><div class="account-cards"><?php foreach ($accounts as $account): ?><article class="account-card"><div class="account-card-top"><span class="account-pill <?= e(account_badge_class($account['account_type'])) ?>"><?= e($account['account_type']) ?></span><button type="button" class="icon-button" aria-label="More options">•••</button></div><p><?= e(mask_account($account['account_number'])) ?></p><strong><?= money($account['balance']) ?></strong><small>Available balance</small></article><?php endforeach; ?></div></section><section class="portal-section"><div class="section-heading portal-heading"><div><p class="eyebrow">Recent activity</p><h2>What moved recently.</h2></div><a class="text-action" href="transactions.php">View all transactions →</a></div><div class="transaction-panel"><?php foreach ($transactions as $transaction): ?><div class="transaction-line"><div class="transaction-icon <?= (float)$transaction['amount'] >= 0 ? 'credit' : 'debit' ?>" aria-hidden="true"><?= (float)$transaction['amount'] >= 0 ? '↓' : '↑' ?></div><div><strong><?= e($transaction['description']) ?></strong><span><?= e($transaction['account_type']) ?> · <?= e(date_label($transaction['transaction_date'])) ?></span></div><b class="<?= (float)$transaction['amount'] >= 0 ? 'amount-credit' : 'amount-debit' ?>"><?= (float)$transaction['amount'] >= 0 ? '+' : '−' ?><?= money(abs((float)$transaction['amount'])) ?></b></div><?php endforeach; ?></div></section></section>
<?php require __DIR__ . '/includes/footer.php'; ?>
